using System;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Shell;using System.Windows.Automation;
public partial class TV {
 readonly Dictionary<Window,Button[]> macControls=new Dictionary<Window,Button[]>();
 static LinearGradientBrush AppleAccent(){return new LinearGradientBrush(new GradientStopCollection{new GradientStop(System.Windows.Media.Color.FromRgb(91,125,255),0),new GradientStop(System.Windows.Media.Color.FromRgb(155,101,240),.5),new GradientStop(System.Windows.Media.Color.FromRgb(235,119,179),1)},new Point(0,0),new Point(1,1));}
 static LinearGradientBrush AppleWash(){return new LinearGradientBrush(new GradientStopCollection{new GradientStop(System.Windows.Media.Color.FromRgb(240,246,255),0),new GradientStop(System.Windows.Media.Color.FromRgb(246,240,255),.55),new GradientStop(System.Windows.Media.Color.FromRgb(255,243,248),1)},new Point(0,0),new Point(1,1));}
 static LinearGradientBrush AppleSelection(){return new LinearGradientBrush(new GradientStopCollection{new GradientStop(System.Windows.Media.Color.FromRgb(222,233,255),0),new GradientStop(System.Windows.Media.Color.FromRgb(240,224,253),1)},new Point(0,0),new Point(1,1));}
 void NormalizeActionButton(Button b,string label){b.MinHeight=36;b.MinWidth=76;b.Padding=new Thickness(14,8,14,8);b.Margin=new Thickness(4);b.HorizontalContentAlignment=HorizontalAlignment.Center;b.VerticalContentAlignment=VerticalAlignment.Center;if(new[]{"连接电视","扫描应用列表","API 分析","连接本地 AI Agent","全部安装","安装此桌面","开始分析","保存配置"}.Contains(label)){b.Tag="Primary";b.Background=AppleAccent();b.Foreground=Brushes.White;b.BorderBrush=Brushes.Transparent;}if(label=="高风险卸载勾选"){b.Tag="Danger";b.Foreground=Color("#BE3349");b.Background=Color("#FFF0F2");b.BorderBrush=Color("#E8A4AE");}}
 void ApplyMacChrome(Window window,FrameworkElement content){if(window.Resources.MergedDictionaries.Count==0){using(var theme=System.IO.File.OpenRead(Root+"Theme.xaml"))window.Resources.MergedDictionaries.Add((ResourceDictionary)System.Windows.Markup.XamlReader.Load(theme));}if(window!=this){window.FontFamily=FontFamily;window.FontSize=FontSize;}macControls[window]=MacFrame.Attach(window,content);window.Closed+=(s,e)=>macControls.Remove(window);}
}
